cd /data; cat orders.csv; python3 - <<'E'
import csv,collections
p={r['product_id'].strip():r for r in csv.DictReader(open('products.csv'))}
t=collections.defaultdict(float)
for r in csv.DictReader(open('orders.csv')):
    k=r['product_id'].strip()
    if k not in p: print("unmatched:",r); continue
    t[p[k]['category']]+=int(r['quantity'])*float(p[k]['price'])
for c,v in sorted(t.items(),key=lambda x:-x[1]): print(f"{c}: {v:g}")
